/// Whether both sources of a two-source instruction read the same register, lanes and modifier.
fn same_operands(ins: &Instruction) -> bool {
    matches!((ins.operand(1), ins.operand(2)), (Ok(a), Ok(b)) if format!("{a:?}") == format!("{b:?}"))
}
/// D3D `ne x, x` (true exactly for NaN lanes) and `eq x, x` (false exactly for NaN lanes), on the bits.
fn nan_self_compare(&mut self, ins: &Instruction, ne: bool) -> Result<()> {
    let mask = self.dest_mask(ins.operand(0)?);
    let a = self.read(ins.operand(1)?, mask, Kind::F)?;
    let nan = self.b.is_nan(a);
    let c = if ne { nan } else { self.b.unary(Uo::LogicalNot, nan) };
    let r = self.b.mask_of(c);
    self.write(ins.operand(0)?, r, false)
}

// `eq x, x` / `ne x, x` is the source's NaN test (D3D: `ne` is true for a NaN lane,
// `eq` false). Compilers that assume finite math fold `x != x` to false and `x == x` to true
// (the original bloom downsample NaN guard vanished on a real GPU), so the test is written
// on the bits like `Builder::is_nan`. Other operand pairs keep the plain comparison.
"eq" | "ne" if Self::same_operands(ins) => self.nan_self_compare(ins, name == "ne")?,

}

/// Inspect the complete decoded inventory without lowering. Inner errors retain typed source diagnostics.
pub fn precision_inventory(
    bytes: &[u8],
) -> Result<std::result::Result<iridia::precision::PrecisionReceipt, PrecisionDiagnostic>> {
    let directory = crate::parts(bytes)?;
    let code = directory
        .iter()
        .find(|c| matches!(&c.kind, b"SHDR" | b"SHEX"))
        .ok_or_else(|| error(0, "missing shader code chunk"))?;
    if code.data.len() % 4 != 0 || code.data.len() > 4_194_304 {
        return Err(error(0, "invalid code length"));
    }
    let words: Vec<u32> = code
        .data
        .as_chunks::<4>()
        .0
        .iter()
        .map(|b| u32::from_le_bytes(*b))
        .collect();
    let decoded = decode(&words).map_err(crate::read)?;
    Ok(precision::inventory(
        &decoded,
        &words,
        code.kind,
        iridia::source_hash(bytes),
    ))

if setup.sigs.is_some() && receipt.is_precision_bearing() {
    return Err(error(
        0,
        format!(
            "PreciseReceiptRemapUnavailable: stage function/phase lifecycle; {:?}",
            receipt.records()
        ),
    ));
}

