//! Preflight original instructions; bind actual arithmetic producers or exact immediate stores.
use super::Lift;
use crate::{Result, error};
use dxbc_reader::decode::{Declared, Decoded, Instruction, Register, Selection};
use iridia::build::{Kind, Val};
use iridia::precision::*;
use naga::{BinaryOperator as Bo, Expression as E, MathFunction as Mf};


/// Structured refusal retains the complete source record, including raw words and operand ordinals.
#[derive(Clone, Debug)]
pub struct PrecisionDiagnostic {
    /// Stable refusal code, not an admission warning.
    pub reason: &'static str,
    /// Original source record. Flags-only refusals have no instruction.
    pub record: Option<SourceInstruction>,
    /// Whole source hash even for a flags-only refusal.
    pub source_sha: String,
    /// Original declarations, preserving absence and duplicate declarations.
    pub flags: Vec<u32>,
}

pub(super) fn inventory(
    decoded: &Decoded,
    words: &[u32],
    chunk: [u8; 4],
    hash: String,
) -> std::result::Result<PrecisionReceipt, PrecisionDiagnostic> {
    let flags: Vec<u32> = decoded
        .declarations
        .iter()
        .filter_map(|d| match d.kind {
            Declared::GlobalFlags(f) => Some(f),
            _ => None,
        })
        .collect();
    let records: Vec<_> = decoded
        .instructions
        .iter()
        .map(|ins| {
            let token = words[ins.word];
            let length = ((token >> 24) & 127) as usize;
            let raw = words[ins.word..ins.word + length].to_vec();
            let bytes: Vec<_> = raw.iter().flat_map(|w| w.to_le_bytes()).collect();
            SourceInstruction {
                reason: if ins.precise_mask() == 0 {
                    PrecisionReason::RefactoringAllowed
                } else {
                    PrecisionReason::ExplicitMask
                },
                source_sha: hash.clone(),
                chunk,
                word: ins.word,
                words: raw,
                digest: iridia::source_hash(&bytes),
                instruction: ins.clone(),
                flags: flags.clone(),
                destinations: ins
                    .destinations_and_sources()
                    .map(|(d, _)| {
                        d.iter()
                            .enumerate()
                            .map(|(ordinal, o)| {
                                let null = o.register == Register::Null;
                                let mask = if null {
                                    0
                                } else {
                                    match o.selection {
                                        Selection::Mask(m) => m,
                                        _ => 0,
                                    }
                                };
                                Destination {
                                    ordinal,
                                    null,
                                    mask,
                                    lanes: super::resources::lanes_of(mask),
                                }
                            })
                            .collect()
                    })
                    .unwrap_or_default(),
            }
        })
        .collect();
    let fail = |reason, record| PrecisionDiagnostic {
        reason,
        record,
        source_sha: hash.clone(),
        flags: flags.clone(),
    };
    let marked = records.iter().find(|r| r.instruction.precise_mask() != 0);
    if flags.len() > 1 {
        return Err(fail("InvalidGlobalFlagsDeclarations", marked.cloned()));
    }
    if !flags.first().is_some_and(|f| f & 1 != 0) {
        return Err(fail(
            if marked.is_some() {
                "PreciseWithoutRefactoringAllowed"
            } else {
                "ImplicitPrecisionContractUnrepresented"
            },
            marked.cloned(),
        ));
    }
    let raw_declarations = decoded.declarations.iter().filter(|d| matches!(d.kind, Declared::ResourceRaw{..}|Declared::ResourceStructured{..})).map(|d| {
        let n=((words[d.word]>>24)&127)as usize;
        RawDeclaration582{word:d.word,words:words[d.word..d.word+n].to_vec(),source_sha:hash.clone()}
    }).collect::<Vec<_>>();
    if let Some(r)=records.iter().find(|r|r.instruction.name()=="ld_raw" && r.instruction.precise_mask()!=0){
        let mut receipt=PrecisionReceipt::new(vec![]);receipt.set_raw_declarations582(raw_declarations.clone());
        if decoded.target()!="vs_5_0" || receipt.check_raw_declaration582().is_err(){return Err(fail("PreciseRawDeclarationProvenanceUnsupported",Some(r.clone())))}
    }
    if let Some(r)=records.iter().find(|r|r.instruction.name()=="sample_l"&&r.instruction.precise_mask()!=0){
        if sample_source648(r).is_err()||decoded.target()!="vs_5_0"||words.get(15..18)!=Some(&[50331738,1073152,0])||words.get(21..25)!=Some(&[67115096,1077248,18,21845]){return Err(fail("PreciseSample648DeclarationUnsupported",Some(r.clone())))}
    }
    for r in &records {
        if r.instruction.name() == "ishl" && r.instruction.precise_mask() != 0
            && !decoded.target().ends_with("_5_0") {
            return Err(fail("PreciseLogicalShiftShaderModelUnsupported", Some(r.clone())));
        }
        let i = &r.instruction;
        let m = i.precise_mask();
        if m == 0 {
            continue;
        }
        let reason = classify(r);
        if let Some(reason) = reason {
            return Err(fail(reason, Some(r.clone())));
        }
    }
    let mut receipt=PrecisionReceipt::new(records);receipt.set_raw_declarations582(raw_declarations);Ok(receipt)
}
fn classify(r: &SourceInstruction) -> Option<&'static str> {
    let i = &r.instruction;
    let m = i.precise_mask();
    let name = i.name();
    if name=="sample_l"{return sample_source648(r).err().map(|_|"PreciseSample648SourceUnsupported")}
    if name == "ld_raw" {
        return raw_load_source582(r).err().map(|_| "PreciseRawLoadProvenanceUnsupported");
    }
    if name == "exp" {
        return scalar_exp_lane(r)
            .err()
            .map(|_| "PreciseExpSourceUnsupported");
    }
    if name == "ishl" {
        return logical_shift_lanes(r).err().map(|_| "PreciseLogicalShiftDomainUnsupported");
    }
    if name == "mov" {
        if register_copy_lanes(r).is_ok() { return None; }
        return exact_immediate_lanes(r).err().map(|e| match e.as_str() {
            "ExactMoveSpecialBitsUnsupported" => "ExactMoveSpecialBitsUnsupported",
            "ExactMoveMinimumPrecisionUnsupported" => "ExactMoveMinimumPrecisionUnsupported",
            "ExactMoveModifierUnsupported" => "ExactMoveModifierUnsupported",
            "ExactMoveMaskUnsupported" => "ExactMoveMaskUnsupported",
            _ => "ExactMoveOperandDomainUnsupported",
        });
    }
    if name == "movc" {
        // Precise raw conditional move (no float interpretation without modifiers).
        return conditional_move_lanes(r).err().map(|e| match e.as_str() {
            "BitExactModifierOrPrecisionUnsupported" => "PreciseConditionalMoveModifierUnsupported",
            "BitExactConditionalMoveOperandDomainUnsupported" => "PreciseConditionalMoveOperandDomainUnsupported",
            _ => "PreciseConditionalMoveSourceUnsupported",
        });
    }
    if name == "lt" {
        // Precise D3D float less-than with explicit operand denormal flush.
        return less_lanes(r).err().map(|e| match e.as_str() {
            "LessModifierOrControlUnsupported" => "PreciseLessModifierOrControlUnsupported",
            "LessPartialPrecisionUnsupported" => "PreciseLessPartialPrecisionUnsupported",
            "LessDestinationUnsupported" => "PreciseLessDestinationUnsupported",
            "LessInputDomainUnsupported" => "PreciseLessInputDomainUnsupported",
            "LessSelectionUnsupported" => "PreciseLessSelectionUnsupported",
            _ => "PreciseLessSourceUnsupported",
        });
    }
    if matches!(name, "sincos" | "rsq" | "div") {
        // Tolerance-checked class (WARP-measured tolerance, WARP-exact edges).
        return tolerance_lanes(r).err().map(|e| match e.as_str() {
            "ToleranceModifierOrControlUnsupported" => "PreciseToleranceModifierOrControlUnsupported",
            "TolerancePartialPrecisionUnsupported" => "PreciseTolerancePartialPrecisionUnsupported",
            "ToleranceDestinationUnsupported" => "PreciseToleranceDestinationUnsupported",
            "ToleranceInputDomainUnsupported" => "PreciseToleranceInputDomainUnsupported",
            "ToleranceDivisorNotMeasured" => "PreciseToleranceDivisorNotMeasured",
            "ToleranceDivisorDomainUnsupported" => "PreciseToleranceDivisorDomainUnsupported",
            _ => "PreciseToleranceSourceUnsupported",
        });
    }
    if name == "max" {
        // Precise max reproducing the measured WARP DXBC result bit-exactly.
        return max_lanes(r).err().map(|e| match e.as_str() {
            "MaxModifierOrControlUnsupported" => "PreciseMaxModifierOrControlUnsupported",
            "MaxPartialPrecisionUnsupported" => "PreciseMaxPartialPrecisionUnsupported",
            "MaxDestinationUnsupported" => "PreciseMaxDestinationUnsupported",
            "MaxInputDomainUnsupported" => "PreciseMaxInputDomainUnsupported",
            "MaxSelectionUnsupported" => "PreciseMaxSelectionUnsupported",
            _ => "PreciseMaxSourceUnsupported",
        });
    }
    if name == "frc" {
        // Precise frc reproducing the measured WARP DXBC result bit-exactly.
        return frac_lanes(r).err().map(|e| match e.as_str() {
            "FracModifierOrControlUnsupported" => "PreciseFracModifierOrControlUnsupported",
            "FracPartialPrecisionUnsupported" => "PreciseFracPartialPrecisionUnsupported",
            "FracDestinationUnsupported" => "PreciseFracDestinationUnsupported",
            "FracInputDomainUnsupported" => "PreciseFracInputDomainUnsupported",
            "FracSelectionUnsupported" => "PreciseFracSelectionUnsupported",
            _ => "PreciseFracSourceUnsupported",
        });
    }
    if name == "round_ni" {
        return round_ni_lanes(r).err().map(|e| match e.as_str() {
            "RoundNiModifierOrControlUnsupported" => "PreciseRoundNiModifierOrControlUnsupported",
            "RoundNiPartialPrecisionUnsupported" => "PreciseRoundNiPartialPrecisionUnsupported",
            "RoundNiDestinationUnsupported" => "PreciseRoundNiDestinationUnsupported",
            "RoundNiInputDomainUnsupported" => "PreciseRoundNiInputDomainUnsupported",
            "RoundNiSelectionUnsupported" => "PreciseRoundNiSelectionUnsupported",
            _ => "PreciseRoundNiSourceUnsupported",
        });
    }
    if matches!(name, "imul" | "umul") && r.destinations.first().is_some_and(|d| !d.null) {
        return Some("PreciseHighMultiplyUnresolved");
    }
    if !matches!(
        name,
        "add" | "mul" | "iadd" | "imul" | "umul" | "dp2" | "dp3" | "dp4"
    ) {
        return Some("PreciseOpcodeUnsupported");
    }
    if i.control & !0xf04 != 0 || !i.extensions.is_empty() {
        return Some("PreciseInstructionControlUnsupported");
    }
    if name == "add" && i.saturate {
        // 865d (R4): strict add + exact saturate, admitted for WARP-measured immediates only.
        return add_sat_lanes(r).err().map(|e| match e.as_str() {
            "AddSatModifierOrControlUnsupported" => "PreciseAddSatModifierOrControlUnsupported",
            "AddSatPartialPrecisionUnsupported" => "PreciseAddSatPartialPrecisionUnsupported",
            "AddSatInputDomainUnsupported" => "PreciseAddSatInputDomainUnsupported",
            "AddSatAddendNotMeasured" => "PreciseAddSatAddendNotMeasured",
            _ => "PreciseAddSatSourceUnsupported",
        });
    }
    if i.saturate {
        return Some("PreciseCompoundModifierUnresolved");
    }
    // Float source neg/abs/abs-neg are exact sign operations (D3D11.3 22.18) carried as
    // explicit operand expressions; integer negate and destination modifiers stay refused.
    if let Err(reason) = source_modifiers(r) {
        return Some(reason);
    }
    if i.operands.iter().any(|o| o.precision != 0) {
        return Some("PreciseMinimumPrecisionUnresolved");
    }
    let live: Vec<_> = r.destinations.iter().filter(|d| !d.null).collect();
    if live.len() != 1 {
        return Some("PreciseDestinationShapeUnresolved");
    }
    let d = live[0];
    if d.mask == 0 {
        return Some("PreciseDestinationShapeUnresolved");
    }
    if m & !d.mask != 0 {
        return Some("PreciseOutsideWrittenMaskUnresolved");
    }
    if name.starts_with("dp") && m != d.mask {
        return Some("PreciseDotMixedBroadcastUnresolved");
    }
    None
}

impl Lift<'_> {
    pub(super) fn bind_producer(
        &mut self,
        ins: &Instruction,
        r: Val,
        args: &[Val],
        dest: usize,
        positions: &[u8],
        controlled: bool,
    ) -> Result<()> {
        self.b.check().map_err(|s| error(ins.word, s))?;
        let expected = match &self.b.function.expressions[r.expr] {
            E::AccessIndex{index:0,..} if ins.name()=="sample_l" => r.kind==Kind::F&&r.width.get()==1&&args.len()==2&&args[0].kind==Kind::F&&args[0].width.get()==2&&args[1].kind==Kind::F&&args[1].width.get()==1,
            E::Compose{components,..} if ins.name()=="ld_raw" => components.len()==4 && args.len()==1 && r.kind==Kind::U && args[0].kind==Kind::U && args[0].width.get()==1,
            E::Select{..} if ins.name()=="ld_raw" => r.width.get()==1 && args.len()==1 && r.kind==Kind::U && args[0].kind==Kind::U && args[0].width.get()==1,
            E::Swizzle { vector, .. } | E::AccessIndex { base: vector, .. } if ins.name() == "mov" => {
                args.len() == 1 && *vector == args[0].expr && r.kind == Kind::U && args[0].kind == Kind::U
            },
            E::Math {
                fun: Mf::Exp2,
                arg,
                arg1: None,
                arg2: None,
                arg3: None,
            } => {
                args.len() == 1
                    && *arg == args[0].expr
                    && r.kind == Kind::F
                    && r.width.get() == 1
                    && args[0].width.get() == 1
            }
            E::Math {
                fun: Mf::Floor,
                arg,
                arg1: None,
                arg2: None,
                arg3: None,
            } if matches!(ins.name(), "round_ni" | "frc") => {
                args.len() == 1
                    && *arg == args[0].expr
                    && r.kind == Kind::F
                    && args[0].kind == Kind::F
                    && r.width == args[0].width
            }
            E::Select { condition, accept, reject } if ins.name() == "movc" => {
                args.len() == 3
                    && matches!(self.b.function.expressions[*condition], E::Binary { op: Bo::NotEqual, left, .. } if left == args[0].expr)
                    && *accept == args[1].expr
                    && *reject == args[2].expr
                    && r.kind == Kind::U
                    && args.iter().all(|a| a.kind == Kind::U && a.width == r.width)
            }
            E::Math { fun: Mf::Sin | Mf::Cos | Mf::InverseSqrt, arg, arg1: None, arg2: None, arg3: None }
                if matches!(ins.name(), "sincos" | "rsq") =>
            {
                args.len() == 1 && *arg == args[0].expr && r.kind == Kind::F && args[0].kind == Kind::F && r.width == args[0].width
            }
            E::Binary { op: Bo::Divide, left, right } if ins.name() == "div" => {
                args.len() == 2
                    && *left == args[0].expr
                    && *right == args[1].expr
                    && r.kind == Kind::F
                    && args.iter().all(|a| a.kind == Kind::F && a.width == r.width)
            }
            E::Binary { op: Bo::Subtract, left, right } if ins.name() == "frc" => {
                args.len() == 2
                    && *left == args[0].expr
                    && *right == args[1].expr
                    && r.kind == Kind::F
                    && args.iter().all(|a| a.kind == Kind::F && a.width == r.width)
            }
            E::Binary { op: Bo::Less, left, right } if matches!(ins.name(), "lt" | "max") => {
                args.len() == 2
                    && *left == args[0].expr
                    && *right == args[1].expr
                    && r.kind == Kind::B
                    && args[0].kind == Kind::F
                    && args[1].kind == Kind::F
                    && r.width == args[0].width
                    && r.width == args[1].width
            }
            E::Binary { op, left, right } => {
                matches!(op, Bo::Add | Bo::Multiply | Bo::ShiftLeft)
                    && *left == args[0].expr
                    && *right == args[1].expr
                    && args[0].kind == args[1].kind
                    && args[0].width == args[1].width
            }
            E::Math {
                fun: Mf::Dot,
                arg,
                arg1: Some(b),
                ..
            } => {
                *arg == args[0].expr
                    && *b == args[1].expr
                    && args[0].kind == Kind::F
                    && args[1].kind == Kind::F
            }
            _ => false,
        };
        if !expected {
            return self.refuse("PreciseProducerMismatch");
        }
        if controlled {
            self.b.function.expression_controls.insert(
                r.expr,
                if ins.name() == "exp" {
                    naga::ArithmeticControl::Exp2F32NoRefactoringV1
                } else if ins.name() == "round_ni"
                    || (ins.name() == "frc" && matches!(self.b.function.expressions[r.expr], E::Math { fun: Mf::Floor, .. }))
                {
                    naga::ArithmeticControl::FloorF32NoRefactoringV1
                } else if ins.name() == "add" && ins.saturate {
                    naga::ArithmeticControl::AddF32StrictV1
                } else if matches!(ins.name(), "sincos" | "rsq" | "div") {
                    naga::ArithmeticControl::ToleranceF32NoRefactoringV1
                } else if matches!(ins.name(), "lt" | "max") {
                    naga::ArithmeticControl::LessF32NoRefactoringV1
                } else {
                    naga::ArithmeticControl::NoContraction
                },
            );
        }
        let owner = FunctionOwner::EntryPoint {
            index: 0,
            name: "main".into(),
        };
        let owned = |v: Val| OwnedExpression {
            module_revision: 0,
            owner: owner.clone(),
            expression: v.expr,
        };
        let lanes = super::resources::lanes_of(self.dest_mask(&ins.operands[dest]));
        self.precision.bind(ProducerBinding {
            source_word: ins.word,
            instance: 0,
            producer: owned(r),
            operands: args.iter().copied().map(owned).collect(),
            kind: r.kind,
            width: r.width,
            input_widths: args.iter().map(|v| v.width).collect(),
            scalar_bytes: 4,
            destination: dest,
            original_lanes: positions.iter().map(|p| lanes[*p as usize]).collect(),
            packed_positions: positions.to_vec(),
            role: if ins.name()=="sample_l"{ProducerRole::SampleExplicitLod648}else if ins.name() == "ld_raw" {
                ProducerRole::RawLoad582
            } else if ins.name() == "mov" {
                ProducerRole::RegisterCopy
            } else if ins.name() == "ishl" {
                ProducerRole::LogicalShift
            } else if ins.name() == "exp" {
                ProducerRole::Exp2Scalar
            } else if ins.name() == "round_ni" {
                ProducerRole::RoundNi
            } else if ins.name() == "lt" {
                ProducerRole::CompareLess
            } else if ins.name() == "max" {
                ProducerRole::MaxCompare
            } else if ins.name() == "add" && ins.saturate {
                ProducerRole::SaturateAdd
            } else if ins.name() == "rsq" {
                ProducerRole::ToleranceRsq
            } else if ins.name() == "div" {
                ProducerRole::ToleranceDiv
            } else if ins.name() == "sincos" {
                if dest == 0 { ProducerRole::ToleranceSin } else { ProducerRole::ToleranceCos }
            } else if ins.name() == "frc" {
                if matches!(self.b.function.expressions[r.expr], E::Math { fun: Mf::Floor, .. }) {
                    ProducerRole::FracFloor
                } else {
                    ProducerRole::FracSubtract
                }
            } else if ins.name() == "movc" {
                ProducerRole::ConditionalMove
            } else if dest == 1 {
                ProducerRole::LowMultiply
            } else if ins.name().starts_with("dp") {
                ProducerRole::DotBroadcast
            } else {
                ProducerRole::Elementwise
            },
            controlled,
        });
        Ok(())
    }
    pub(super) fn precise_instruction(&mut self, ins: &Instruction) -> Result<()> {
        let name = ins.name();
        if name=="sample_l"{return self.sample(ins)}
        if name == "ld_raw" { return self.load_raw(ins); }
        if name == "ishl" {
            let d = &ins.operands[0];
            let mask = self.dest_mask(d);
            let a = self.read(&ins.operands[1], mask, Kind::U)?;
            let b = self.read(&ins.operands[2], mask, Kind::U)?;
            let count = self.b.d3d_shift_count(b);
            let r = self.b.binary(Bo::ShiftLeft, a, count);
            let positions = (0..r.width.get()).collect::<Vec<_>>();
            self.bind_producer(ins, r, &[a, count], 0, &positions, false)?;
            return self.write(d, r, false);
        }
        let copy865 = name == "mov"
            && self.precision.records().iter().find(|r| r.word == ins.word).is_some_and(|r| register_copy_lanes(r).is_ok());
        if name == "mov" && (ins.operands[0].register == Register::Output || copy865) {
            let record = self.precision.records().iter().find(|r| r.word == ins.word).unwrap();
            let selected = register_copy_lanes(record).map_err(|e| error(ins.word, e))?;
            let base = self.reg_value(&ins.operands[1])?;
            let v = self.b.swizzle(base, &selected);
            let positions = (0..v.width.get()).collect::<Vec<_>>();
            self.bind_producer(ins, v, &[base], 0, &positions, false)?;
            return self.write(&ins.operands[0], v, false);
        }
        if name == "mov" {
            let d = &ins.operands[0];
            let v = self.read(&ins.operands[1], self.dest_mask(d), Kind::U)?;
            return self.write(d, v, false);
        }
        if name == "movc" {
            // Raw conditional move. All three sources are read (as raw u32 bits)
            // before the write; the condition is "any bit set".
            let d = &ins.operands[0];
            let mask = self.dest_mask(d);
            let c = self.read(&ins.operands[1], mask, Kind::U)?;
            let a = self.read(&ins.operands[2], mask, Kind::U)?;
            let b = self.read(&ins.operands[3], mask, Kind::U)?;
            let zero = self.b.lit_u(0);
            let cond = self.b.binary(Bo::NotEqual, c, zero);
            let r = self.b.select(cond, a, b);
            let positions = (0..r.width.get()).collect::<Vec<_>>();
            self.bind_producer(ins, r, &[c, a, b], 0, &positions, false)?;
            return self.write(d, r, false);
        }
        if name == "lt" {
            // D3D lt flushes denormal inputs (to the zero of the same sign) before an
            // ordered compare; the result is the 0xFFFFFFFF/0 mask. Integer-only flush, so the
            // compare never sees a denormal on any target. Sources are read before the write.
            let d = &ins.operands[0];
            let mask = self.dest_mask(d);
            // 865d (R3): raw u32 reads; f32 exists only as the strict compare's operands.
            let a = self.read(&ins.operands[1], mask, Kind::U)?;
            let b = self.read(&ins.operands[2], mask, Kind::U)?;
            let (sa, sb) = (self.flush_bits865e(a), self.flush_bits865e(b));
            let (fa, fb) = (self.b.bitcast(sa, Kind::F), self.b.bitcast(sb, Kind::F));
            let c = self.b.binary(Bo::Less, fa, fb);
            let positions = (0..c.width.get()).collect::<Vec<_>>();
            self.bind_producer(ins, c, &[fa, fb], 0, &positions, true)?;
            let r = self.b.mask_of(c);
            return self.write(d, r, false);
        }
        if name == "add" && ins.saturate {
            // 865d (R4): strict add (AddF32StrictV1), then the exact u32 saturate of its bits.
            let d = &ins.operands[0];
            let mask = self.dest_mask(d);
            let a = self.read(&ins.operands[1], mask, Kind::F)?;
            let c = self.read(&ins.operands[2], mask, Kind::F)?;
            let s = self.b.binary(Bo::Add, a, c);
            let positions = (0..s.width.get()).collect::<Vec<_>>();
            self.bind_producer(ins, s, &[a, c], 0, &positions, true)?;
            let rb = self.b.bitcast(s, Kind::U);
            let tiny = self.b.lit_u(SAT_SMALLEST_NORMAL);
            let below_normal = self.b.binary(Bo::Less, rb, tiny);
            let one = self.b.lit_u(SAT_ONE);
            let at_most_one = self.b.binary(Bo::LessEqual, rb, one);
            let infinity = self.b.lit_u(SAT_INFINITY);
            let at_most_infinity = self.b.binary(Bo::LessEqual, rb, infinity);
            let (one2, zero) = (self.b.lit_u(SAT_ONE), self.b.lit_u(0));
            let large = self.b.select(at_most_infinity, one2, zero);
            let unit = self.b.select(at_most_one, rb, large);
            let zero2 = self.b.lit_u(0);
            let result = self.b.select(below_normal, zero2, unit);
            return self.write(d, result, false);
        }
        if matches!(name, "sincos" | "rsq" | "div") {
            // Tolerance-checked class. Intrinsic under ToleranceF32NoRefactoringV1 on the
            // finite normal path; WARP-exact NaN/Inf/zero/denormal/negative results selected in u32.
            let record = self.precision.records().iter().find(|r| r.word == ins.word).unwrap();
            let t = tolerance_lanes(record).map_err(|e| error(ins.word, e))?;
            let d = &ins.operands[t.destination];
            let mask = self.dest_mask(d);
            let src = &ins.operands[if name == "sincos" { 2 } else { 1 }];
            let bits = self.read(src, mask, Kind::U)?;
            let x = self.b.bitcast(bits, Kind::F);
            let positions = (0..x.width.get()).collect::<Vec<_>>();
            let r = if t.op == ToleranceOp::Div {
                let divisor = self.read(&ins.operands[2], mask, Kind::F)?;
                let r = self.b.binary(Bo::Divide, x, divisor);
                self.bind_producer(ins, r, &[x, divisor], t.destination, &positions, true)?;
                r
            } else {
                let fun = match t.op { ToleranceOp::Sin => Mf::Sin, ToleranceOp::Cos => Mf::Cos, _ => Mf::InverseSqrt };
                let r = self.b.math(fun, &[x]);
                self.bind_producer(ins, r, &[x], t.destination, &positions, true)?;
                r
            };
            let rb = self.b.bitcast(r, Kind::U);
            let rflush = self.flush_bits865e(rb);
            let sign_mask = self.b.lit_u(TOL_SIGN_MASK);
            let sign = self.b.binary(Bo::And, bits, sign_mask);
            let zero = self.b.lit_u(0);
            let negative = self.b.binary(Bo::NotEqual, sign, zero);
            let finite = if t.op == ToleranceOp::Rsq {
                let invalid = self.b.lit_u(TOL_INVALID_NAN);
                self.b.select(negative, invalid, rflush)
            } else {
                rflush
            };
            let pair = |s: &mut Self, (n, p): (u32, u32)| {
                let (n, p) = (s.b.lit_u(n), s.b.lit_u(p));
                s.b.select(negative, n, p)
            };
            let zero_result = pair(self, t.op.zero());
            let infinity_result = pair(self, t.op.infinity());
            let exponent_mask = self.b.lit_u(TOL_EXPONENT_MASK);
            let exponent = self.b.binary(Bo::And, bits, exponent_mask);
            let zero_exponent = self.b.lit_u(0);
            let zero_or_denormal = self.b.binary(Bo::Equal, exponent, zero_exponent);
            let all_ones = self.b.lit_u(TOL_EXPONENT_MASK);
            let special = self.b.binary(Bo::Equal, exponent, all_ones);
            let mantissa_mask = self.b.lit_u(TOL_MANTISSA_MASK);
            let mantissa = self.b.binary(Bo::And, bits, mantissa_mask);
            let zero_mantissa = self.b.lit_u(0);
            let is_nan = self.b.binary(Bo::NotEqual, mantissa, zero_mantissa);
            let quiet_bit = self.b.lit_u(TOL_QUIET_BIT);
            let quiet = self.b.binary(Bo::InclusiveOr, bits, quiet_bit);
            let nan = self.b.select(is_nan, quiet, infinity_result);
            let inner = self.b.select(zero_or_denormal, zero_result, finite);
            let result = self.b.select(special, nan, inner);
            return self.write(d, result, false);
        }
        if name == "max" {
            // The WARP-measured D3D max (see iridia precision::max865e): integer
            // flush of both sources, controlled ordered Less, integer selection.
            let d = &ins.operands[0];
            let mask = self.dest_mask(d);
            let b0 = self.read(&ins.operands[1], mask, Kind::U)?;
            let b1 = self.read(&ins.operands[2], mask, Kind::U)?;
            let (s0, s1) = (self.flush_bits865e(b0), self.flush_bits865e(b1));
            let (x0, x1) = (self.b.bitcast(s0, Kind::F), self.b.bitcast(s1, Kind::F));
            let greater = self.b.binary(Bo::Less, x1, x0);
            let positions = (0..greater.width.get()).collect::<Vec<_>>();
            self.bind_producer(ins, greater, &[x1, x0], 0, &positions, true)?;
            let pick = self.b.select(greater, s0, s1);
            let magnitude_mask = self.b.lit_u(MAX_MAGNITUDE_MASK);
            let magnitude = self.b.binary(Bo::And, b1, magnitude_mask);
            let infinity = self.b.lit_u(MAX_INFINITY);
            let src1_nan = self.b.binary(Bo::Greater, magnitude, infinity);
            let result = self.b.select(src1_nan, b0, pick);
            return self.write(d, result, false);
        }
        if name == "frc" {
            // The WARP-measured D3D frc (see iridia precision::frac865d). Integer
            // flush, controlled floor and subtract, then integer clamp and NaN/Inf selection.
            let d = &ins.operands[0];
            let mask = self.dest_mask(d);
            // 865d (R3): raw u32 read.
            let bits = self.read(&ins.operands[1], mask, Kind::U)?;
            let exponent_mask = self.b.lit_u(FRAC_EXPONENT_MASK);
            let exponent = self.b.binary(Bo::And, bits, exponent_mask);
            let zero = self.b.lit_u(0);
            let denormal_or_zero = self.b.binary(Bo::Equal, exponent, zero);
            let sign_mask = self.b.lit_u(FRAC_SIGN_MASK);
            let signed_zero = self.b.binary(Bo::And, bits, sign_mask);
            let flushed = self.b.select(denormal_or_zero, signed_zero, bits);
            let x = self.b.bitcast(flushed, Kind::F);
            let floor = self.b.math(Mf::Floor, &[x]);
            let positions = (0..floor.width.get()).collect::<Vec<_>>();
            self.bind_producer(ins, floor, &[x], 0, &positions, true)?;
            let fraction = self.b.binary(Bo::Subtract, x, floor);
            self.bind_producer(ins, fraction, &[x, floor], 0, &positions, true)?;
            let fraction_raw = self.b.bitcast(fraction, Kind::U);
            // 865d (R3): x - floor(x) is never negative; mask an NSZ zero-sign flip (R2 0x7).
            let magnitude_mask = self.b.lit_u(0x7fff_ffff);
            let fraction_bits = self.b.binary(Bo::And, fraction_raw, magnitude_mask);
            let one = self.b.lit_u(FRAC_ONE);
            let is_one = self.b.binary(Bo::Equal, fraction_bits, one);
            let below_one = self.b.lit_u(FRAC_BELOW_ONE);
            let clamped = self.b.select(is_one, below_one, fraction_bits);
            let all_ones_exponent = self.b.lit_u(FRAC_EXPONENT_MASK);
            let special = self.b.binary(Bo::Equal, exponent, all_ones_exponent);
            let mantissa_mask = self.b.lit_u(FRAC_MANTISSA_MASK);
            let mantissa = self.b.binary(Bo::And, bits, mantissa_mask);
            let zero_mantissa = self.b.lit_u(0);
            let is_nan = self.b.binary(Bo::NotEqual, mantissa, zero_mantissa);
            let quiet_bit = self.b.lit_u(FRAC_QUIET_BIT);
            let quiet = self.b.binary(Bo::InclusiveOr, bits, quiet_bit);
            let infinity_nan = self.b.lit_u(FRAC_INFINITY_NAN);
            let nan = self.b.select(is_nan, quiet, infinity_nan);
            let result = self.b.select(special, nan, clamped);
            return self.write(d, result, false);
        }
        if name == "round_ni" {
            // Source lanes are snapshotted by the read before the write.
            let d = &ins.operands[0];
            let a = self.read(&ins.operands[1], self.dest_mask(d), Kind::F)?;
            let r = self.b.math(Mf::Floor, &[a]);
            let positions = (0..r.width.get()).collect::<Vec<_>>();
            self.bind_producer(ins, r, &[a], 0, &positions, true)?;
            // 865d (R3): reinterpret the strict floor's result once, then store raw bits.
            let bits = self.b.bitcast(r, Kind::U);
            return self.write(d, bits, false);
        }
        if name == "exp" {
            let d = &ins.operands[0];
            let a = self.read(&ins.operands[1], self.dest_mask(d), Kind::F)?;
            let r = self.b.math(Mf::Exp2, &[a]);
            self.bind_producer(ins, r, &[a], 0, &[0], true)?;
            return self.write(d, r, false);
        }
        let dest = if matches!(name, "imul" | "umul") {
            1
        } else {
            0
        };
        let d = &ins.operands[dest];
        let mask = self.dest_mask(d);
        let lanes = super::resources::lanes_of(mask);
        let all: Vec<u8> = (0..lanes.len() as u8).collect();
        if name.starts_with("dp") {
            let n = match name {
                "dp2" => 2,
                "dp3" => 3,
                _ => 4,
            };
            let input: Vec<u8> = (0..n).collect();
            let a = self.read_lanes(&ins.operands[1], &input, Kind::F)?;
            let b = self.read_lanes(&ins.operands[2], &input, Kind::F)?;
            let r = self.b.math(Mf::Dot, &[a, b]);
            self.bind_producer(ins, r, &[a, b], dest, &all, true)?;
            return self.write(d, r, false);
        }
        let kind = if matches!(name, "add" | "mul") {
            Kind::F
        } else {
            Kind::U
        };
        let op = if matches!(name, "add" | "iadd") {
            Bo::Add
        } else {
            Bo::Multiply
        };
        // Snapshot both operands before any scatter, including source/destination aliasing.
        let (a, b) = if dest == 1 {
            let aw = self.read_lanes(&ins.operands[2], &[0, 1, 2, 3], kind)?;
            let bw = self.read_lanes(&ins.operands[3], &[0, 1, 2, 3], kind)?;
            (self.b.swizzle(aw, &lanes), self.b.swizzle(bw, &lanes))
        } else {
            (
                self.read(&ins.operands[1], mask, kind)?,
                self.read(&ins.operands[2], mask, kind)?,
            )
        };
        let (marked, ordinary): (Vec<u8>, Vec<u8>) = all
            .iter()
            .copied()
            .partition(|p| ins.precise_mask() & (1 << lanes[*p as usize]) != 0);
        let r = if ordinary.is_empty() {
            let r = self.b.binary(op, a, b);
            self.bind_producer(ins, r, &[a, b], dest, &all, true)?;
            r
        } else {
            let ap = self.b.swizzle(a, &marked);
            let bp = self.b.swizzle(b, &marked);
            let au = self.b.swizzle(a, &ordinary);
            let bu = self.b.swizzle(b, &ordinary);
            let rp = self.b.binary(op, ap, bp);
            self.bind_producer(ins, rp, &[ap, bp], dest, &marked, true)?;
            let ru = self.b.binary(op, au, bu);
            self.bind_producer(ins, ru, &[au, bu], dest, &ordinary, false)?;
            let parts: Vec<_> = all
                .iter()
                .map(|p| {
                    if let Some(k) = marked.iter().position(|v| v == p) {
                        self.b.lane(rp, k as u8)
                    } else {
                        self.b
                            .lane(ru, ordinary.iter().position(|v| v == p).unwrap() as u8)
                    }
                })
                .collect();
            self.b.compose(&parts)
        };
        self.write(d, r, false)
    }
}

impl Lift<'_> {
    /// Exact integer denormal flush of an f32 value: a denormal becomes the zero of the same
    /// sign; zeros, normals, infinities and NaN bit patterns are unchanged.
    /// The integer denormal flush of raw u32 bits (no reinterpretation).
    fn flush_bits865e(&mut self, bits: Val) -> Val {
        let exponent_mask = self.b.lit_u(LESS_EXPONENT_MASK);
        let exponent = self.b.binary(Bo::And, bits, exponent_mask);
        let zero = self.b.lit_u(0);
        let denormal_or_zero = self.b.binary(Bo::Equal, exponent, zero);
        let sign_mask = self.b.lit_u(LESS_SIGN_MASK);
        let signed_zero = self.b.binary(Bo::And, bits, sign_mask);
        self.b.select(denormal_or_zero, signed_zero, bits)
    }
    fn flush_denormal865(&mut self, x: Val) -> Val {
        let bits = self.b.bitcast(x, Kind::U);
        let exponent_mask = self.b.lit_u(LESS_EXPONENT_MASK);
        let exponent = self.b.binary(Bo::And, bits, exponent_mask);
        let zero = self.b.lit_u(0);
        let denormal_or_zero = self.b.binary(Bo::Equal, exponent, zero);
        let sign_mask = self.b.lit_u(LESS_SIGN_MASK);
        let signed_zero = self.b.binary(Bo::And, bits, sign_mask);
        let flushed = self.b.select(denormal_or_zero, signed_zero, bits);
        self.b.bitcast(flushed, Kind::F)
    }
    pub(super) fn record_exact_store(
        &mut self,
        pointer: naga::Handle<E>,
        value: naga::Handle<E>,
        lanes: &[u8],
    ) -> Result<()> {
        let Some(r) = self.precision.records().iter().find(|r| {
            r.word == self.word
                && r.instruction.name() == "mov"
                && r.instruction.precise_mask() != 0
        }) else {
            return Ok(());
        };
        if register_copy_lanes(r).is_ok() { return Ok(()); }
        let selected = exact_immediate_lanes(r)
            .map_err(|s| error(self.word, s))?
            .into_iter()
            .filter(|l| lanes.contains(&l.destination))
            .collect();
        let owned = |expression| OwnedExpression {
            module_revision: 0,
            owner: FunctionOwner::EntryPoint {
                index: 0,
                name: "main".into(),
            },
            expression,
        };
        self.precision
            .bind_exact_assignment(self.word, owned(pointer), owned(value), selected);
        Ok(())
    }
}

